// Generated by `just generate` from `src/kernel/shell/scan.ts`. Edit the source and run `just generate`.
// The scan of `shell.ts`: one pass over a text with a stack of frames, one for each substitution, parenthesis, and backtick.
// The function is pure and imports only `shellkinds.ts` and the files of this folder.

import { RESERVED } from "../shellkinds.ts";
import { ansiEscape } from "./ansi-c.ts";
import { expandBraces } from "./braces.ts";
import { delimiterAt } from "./delimiter.ts";

/** A frame of the scan: one `$(`, backtick, or parenthesis, with the words of its command so far. */
type Frame = {
  closer: string | null;
  body: boolean;
  line: string[];
  word: string | null;
  quote: string | null;
  skip: string | false;
  heredocs: Heredoc[];
  outs: string[];
  start: number | null;
  raws: string[];
  marks: number[];
};

/** A heredoc that the scan reads after the end of its line. */
type Heredoc = {
  delimiter: string;
  quoted: boolean;
  head: string[];
  outs: string[];
};

/** The quote states of an ANSI-C quote (`$'...'`): the text, and the text after a `\0`, which the shell drops. */
const ANSI = "$'";
const ANSI_DROP = "$'\0";
const ansi = (f: Frame): boolean => f.quote === ANSI || f.quote === ANSI_DROP;

const frame = (
  closer: string | null,
  body = false,
  start: number | null = null,
): Frame => ({
  closer,
  body,
  line: [],
  word: null,
  quote: null,
  skip: false,
  heredocs: [],
  outs: [],
  start,
  raws: [],
  marks: [],
});

/**
 * One pass over `text` with a stack of frames, one for each `$(`, backtick, and parenthesis.
 * `emit(argv)` gets each simple command.
 * `redirect(op, target, line)` gets each redirection operator with the word after it and the words of its command so far.
 * `heredoc(doc, quoted, head, outs)` gets each heredoc body with the words of its command and the output targets of that command.
 * `background(line)` gets the words of each command that a lone `&` ends, and an empty list after a group such as `(a; b) &`.
 * The `&` of `&&`, `&>`, `|&`, and `>&` does not start a background job.
 */
export const scan = (
  text: string,
  emit: (argv: string[]) => void,
  body: boolean,
  redirect: (op: string, target: string, line: string[]) => void,
  heredoc: (
    doc: string,
    quoted: boolean,
    head: string[],
    outs: string[],
  ) => void,
  background: (line: string[]) => void = () => {},
): void => {
  const first = frame(null, body);
  if (body) first.quote = '"';
  const stack = [first];
  const push = (f: Frame) => {
    if (f.word !== null) {
      // A word that is only substitutions is unreadable, so it is `""`, as before.
      const w = f.word === f.raws.join("") ? "" : f.word;
      if (f.skip) {
        redirect(f.skip, w, f.line);
        if (f.skip.includes(">")) f.outs.push(w);
      } else if (w && f.marks.length) f.line.push(...expandBraces(w, f.marks));
      else f.line.push(w);
      f.skip = false;
    }
    f.word = null;
    f.raws = [];
    f.marks = [];
  };
  const end = (f: Frame) => {
    push(f);
    while (f.line.length && RESERVED.has(f.line[0] as string)) f.line.shift();
    // The text of an unquoted heredoc body is data, so only its substitutions are commands.
    if (f.line.length && !f.body) emit(f.line);
    f.line = [];
    f.outs = [];
  };
  // The source text of a substitution goes into its word, so the words after it stay with it.
  const addRaw = (f: Frame, raw: string) => {
    f.word = (f.word ?? "") + raw;
    f.raws.push(raw);
  };
  const open = (f: Frame, closer: string, at: number) => {
    f.word ??= "";
    stack.push(frame(closer, false, at));
  };
  const close = (f: Frame, at: number) => {
    end(f);
    stack.pop();
    if (f.start !== null)
      addRaw(stack.at(-1) as Frame, text.slice(f.start, at + 1));
  };
  for (let i = 0; i < text.length; i++) {
    const f = stack.at(-1) as Frame;
    const c = text[i] as string;
    if (c === "\\" && i + 1 < text.length && f.quote !== "'" && !ansi(f)) {
      const n = text[++i] as string;
      if (n === "\n") continue;
      f.word =
        (f.word ?? "") + (f.quote && !'$`"\\'.includes(n) ? "\\" : "") + n;
    } else if (f.quote === "'") {
      if (c === "'") f.quote = null;
      else f.word += c;
    } else if (ansi(f)) {
      // A `\0` ends the text of the quote, so the characters after it up to the quote are dropped.
      if (c === "'") f.quote = null;
      else if (c === "\\" && i + 1 < text.length) {
        const { char, last } = ansiEscape(text, i + 1);
        i = last;
        if (char === "\0") f.quote = ANSI_DROP;
        else if (f.quote === ANSI) f.word += char;
      } else if (f.quote === ANSI) f.word += c;
    } else if (f.quote === '"') {
      if (c === '"' && !f.body) f.quote = null;
      else if (c === "$" && text[i + 1] === "(") {
        open(f, ")", i);
        i++;
      } else if (c === "`") open(f, "`", i);
      else f.word = (f.word ?? "") + c;
    } else if (c === "`") {
      if (f.closer === "`") close(f, i);
      else open(f, "`", i);
    } else if (c === "$" && text[i + 1] === "(") {
      open(f, ")", i);
      i++;
    } else if (c === "$" && text[i + 1] === "'") {
      f.quote = ANSI;
      f.word ??= "";
      i++;
    } else if (c === "'" || c === '"') {
      f.quote = c;
      f.word ??= "";
    } else if (c === "#" && f.word === null) {
      const nl = text.indexOf("\n", i);
      i = nl < 0 ? text.length : nl - 1;
    } else if (c === "<" && text[i + 1] === "<" && text[i + 2] !== "<") {
      const at = text[i + 2] === "-" ? i + 3 : i + 2;
      const d = delimiterAt(text, at);
      if (d)
        f.heredocs.push({
          delimiter: d.word,
          quoted: d.quoted,
          head: [...f.line],
          outs: f.outs,
        });
      i = (d ? d.end : at) - 1;
      push(f);
    } else if (c === "<" || c === ">") {
      if (f.word !== null && /^\d+$/.test(f.word)) f.word = null;
      push(f);
      const from = i;
      while ("<>".includes(text[i + 1] ?? " ")) i++;
      if ("&|".includes(text[i + 1] ?? " ")) i++;
      f.skip = text.slice(from, i + 1);
    } else if (c === "\n") {
      end(f);
      let pos = i + 1;
      for (const { delimiter, quoted, head, outs } of f.heredocs.splice(0)) {
        const start = pos;
        let stop = pos;
        while (pos < text.length) {
          const nl = text.indexOf("\n", pos);
          const line = text.slice(pos, nl < 0 ? text.length : nl);
          const next = nl < 0 ? text.length : nl + 1;
          if (line.trim() === delimiter) break;
          pos = stop = next;
        }
        const doc = text.slice(start, stop);
        if (stop > start) heredoc(doc, quoted, head, outs);
        const nl = text.indexOf("\n", pos);
        pos = nl < 0 ? text.length : nl + 1;
      }
      i = pos - 1;
    } else if (c === "(") {
      end(f);
      f.skip = false;
      stack.push(frame(")"));
    } else if (c === ")") {
      if (f.closer === ")") close(f, i);
      else end(f);
    } else if (";&|".includes(c)) {
      if (
        c === "&" &&
        !f.body &&
        !"&>".includes(text[i + 1] ?? " ") &&
        !"&|".includes(text[i - 1] ?? " ")
      ) {
        push(f);
        background([...f.line]);
      }
      end(f);
    } else if (/\s/.test(c)) push(f);
    else {
      // An unquoted brace or comma can expand, except the brace of `${`.
      if ("{,}".includes(c) && !(c === "{" && text[i - 1] === "$"))
        f.marks.push((f.word ?? "").length);
      f.word = (f.word ?? "") + c;
    }
  }
  while (stack.length) {
    const top = stack.pop() as Frame;
    if (top.start !== null)
      addRaw(stack.at(-1) as Frame, text.slice(top.start));
    end(top);
  }
};

